const projectId = $('Receive Project').first().json.project_id;
const costRow = $('Load Cost Estimate').first().json;
const rawBreakdown = costRow.breakdown;
const breakdown = typeof rawBreakdown === 'string'
  ? JSON.parse(rawBreakdown)
  : (Array.isArray(rawBreakdown) ? rawBreakdown : []);
const materials = $('Load Materials').all().map(i => i.json).filter(m => m.id);

const TRADE_MAP = [
  { keywords: ['demolic', 'derribo', 'tabique', 'ladrillo', 'albanil', 'obra general', 'mamposter', 'solera', 'forjado', 'estructura', 'revestimiento'], trade_type: 'albanileria', label: 'Albañilería y obra general' },
  { keywords: ['fontaner', 'plomer', 'inodoro', 'lavabo', 'ducha', 'bañera', 'desague', 'saneamient', 'sanitario', 'agua'], trade_type: 'fontaneria', label: 'Fontanería y sanitarios' },
  { keywords: ['electric', 'iluminac', 'enchufe', 'cuadro', 'cableado', 'mecanismo', 'luminaria'], trade_type: 'electricidad', label: 'Electricidad' },
  { keywords: ['cocina', 'encimera', 'electrodomest', 'campana'], trade_type: 'cocina', label: 'Instalación de cocina' },
  { keywords: ['armario', 'mueble a medida', 'vestidor'], trade_type: 'armarios', label: 'Armarios y muebles a medida' },
  { keywords: ['ventana', 'persiana', 'vidrio', 'acristalamiento'], trade_type: 'ventanas', label: 'Ventanas y carpintería exterior' },
  { keywords: ['puerta', 'carpinter', 'tarima', 'parquet', 'suelo madera'], trade_type: 'carpinteria', label: 'Carpintería interior' },
  { keywords: ['cerrajer', 'reja', 'barandil', 'herreria', 'metalic', 'acero'], trade_type: 'carpinteria_metalica', label: 'Carpintería metálica y cerrajería' },
  { keywords: ['pintura', 'pintar', 'lacado', 'barniz', 'esmalte'], trade_type: 'pintura', label: 'Pintura' },
  { keywords: ['climat', 'aire acondi', 'calefacc', 'radiador', 'suelo radiante', 'hvac', 'fancoil'], trade_type: 'climatizacion', label: 'Climatización' },
];

function normalize(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
}

function detectTradeType(text) {
  const n = normalize(text);
  for (const entry of TRADE_MAP) {
    for (const kw of entry.keywords) {
      if (n.includes(kw)) return entry;
    }
  }
  return { trade_type: 'otro', label: 'Otros trabajos' };
}

const grouped = {};

for (const item of breakdown) {
  const entry = detectTradeType(item.partida || item.description || '');
  const key = entry.trade_type;
  if (!grouped[key]) grouped[key] = { label: entry.label, partidas: [], total: 0 };
  grouped[key].partidas.push(item);
  grouped[key].total += parseFloat(item.importe || item.amount || 0);
}

if (Object.keys(grouped).length === 0 && materials.length > 0) {
  for (const mat of materials) {
    const entry = detectTradeType(mat.name || mat.category || '');
    const key = entry.trade_type;
    if (!grouped[key]) grouped[key] = { label: entry.label, partidas: [], total: 0 };
    grouped[key].partidas.push({ partida: mat.name, cantidad: mat.quantity_estimated, importe: mat.total_estimated });
    grouped[key].total += parseFloat(mat.total_estimated || 0);
  }
}

if (Object.keys(grouped).length === 0) {
  return [{ json: {
    project_id: projectId,
    trade_type: 'albanileria',
    scope_description: 'Obra general — sin desglose disponible',
    scope_details: JSON.stringify([]),
    status: 'prepared'
  } }];
}

return Object.entries(grouped).map(([trade_type, data]) => {
  const partidaLabels = data.partidas
    .map(p => p.partida || p.description || '')
    .filter(Boolean)
    .slice(0, 3)
    .join(', ');
  return { json: {
    project_id: projectId,
    trade_type,
    scope_description: data.label + (partidaLabels ? ': ' + partidaLabels : ''),
    scope_details: JSON.stringify(data.partidas),
    status: 'prepared'
  } };
});

const assignments = $('Map to Gremios').all();
return [{ json: {
  status: 'complete',
  trades_count: assignments.length,
  trade_types: assignments.map(a => a.json.trade_type)
} }];
